    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',17,NULL,NULL,'در کلاس واژه‌ای را نمی‌فهمی؛ از مدرس بخواه آن را دوباره توضیح دهد.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"در کلاس واژه‌ای را نمی‌فهمی؛ از مدرس بخواه آن را دوباره توضیح دهد.","scenario_fa":"در کلاس واژه‌ای را نمی‌فهمی؛ از مدرس بخواه آن را دوباره توضیح دهد.","accepted":["Erklären Sie das Wort bitte noch einmal.","Bitte erklären Sie dieses Wort."],"acceptedIntents":["Erklären Sie das Wort bitte noch einmal.","Bitte erklären Sie dieses Wort."],"accepted_intents":["Erklären Sie das Wort bitte noch einmal.","Bitte erklären Sie dieses Wort."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',10));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',18,NULL,NULL,'مدرس می‌پرسد آمادهٔ خواندن هستی؛ بگو جمله را آهسته و بلند می‌خوانی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"مدرس می‌پرسد آمادهٔ خواندن هستی؛ بگو جمله را آهسته و بلند می‌خوانی.","scenario_fa":"مدرس می‌پرسد آمادهٔ خواندن هستی؛ بگو جمله را آهسته و بلند می‌خوانی.","accepted":["Ich lese den Satz langsam und laut.","Ja, ich kann jetzt laut lesen."],"acceptedIntents":["Ich lese den Satz langsam und laut.","Ja, ich kann jetzt laut lesen."],"accepted_intents":["Ich lese den Satz langsam und laut.","Ja, ich kann jetzt laut lesen."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',10));
