    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'در پایان کلاس هنوز پاسخ یک تمرین را نفهمیده‌ای؛ مؤدبانه درخواست تکرار کن.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"در پایان کلاس هنوز پاسخ یک تمرین را نفهمیده‌ای؛ مؤدبانه درخواست تکرار کن.","scenario_fa":"در پایان کلاس هنوز پاسخ یک تمرین را نفهمیده‌ای؛ مؤدبانه درخواست تکرار کن.","accepted":["Können Sie die Antwort bitte wiederholen?","Bitte sagen Sie die Antwort noch einmal."],"acceptedIntents":["Können Sie die Antwort bitte wiederholen?","Bitte sagen Sie die Antwort noch einmal."],"accepted_intents":["Können Sie die Antwort bitte wiederholen?","Bitte sagen Sie die Antwort noch einmal."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',10));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'لنا می‌پرسد بعد از کلاس چه می‌کنی؛ بگو امروز در خانه تمرین می‌کنی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"لنا می‌پرسد بعد از کلاس چه می‌کنی؛ بگو امروز در خانه تمرین می‌کنی.","scenario_fa":"لنا می‌پرسد بعد از کلاس چه می‌کنی؛ بگو امروز در خانه تمرین می‌کنی.","accepted":["Ich übe heute zu Hause.","Heute möchte ich zu Hause weiter üben."],"acceptedIntents":["Ich übe heute zu Hause.","Heute möchte ich zu Hause weiter üben."],"accepted_intents":["Ich übe heute zu Hause.","Heute möchte ich zu Hause weiter üben."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',10));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>47 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0010' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=10;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_010()$$
